export const BookInfo = ({image, author, name, year}) =>{
    return(
    <div>
        <section>
            <h2>{name}</h2>
        <img
        className={scss.img}
        src={require(`../../covers/${image}`)}
        alt="adss"
      />
        </section>
    </div>
    )
}
